// Minimalistic JS Action Classifier
const msg = ($json.body?.message || '').toLowerCase();
const isShelter = /kayu|shelter|tenda|teduh/.test(msg);
const isFood = /kelapa|air|makan|minum/.test(msg);

const content = isShelter
  ? '🪵 Tenda bivak darurat selesai dibangun di bawah tebing batu! (Stamina -15, Proteksi Badai +80%).'
  : isFood
  ? '🥥 Kamu memetik 2 buah kelapa segar & meminum air mata air. (Stamina +35, Rasa Lapar 0%).'
  : `🏝️ Aksi survival: "${$json.body?.message}". Badai tropis semakin mendekat ke pulau!`;

const chips = isShelter
  ? ['Nyalakan api unggun', 'Cari makanan', 'Istirahat di tenda']
  : isFood
  ? ['Bangun tempat berteduh', 'Buat sinyal SOS', 'Eksplorasi hutan']
  : ['Cari perlindungan gua', 'Kumpulkan kayu bakar', 'Periksa kapal karam'];

return { json: { content, chips } };
